<script setup>
import {onBeforeUnmount,onMounted,ref} from 'vue'
import {listAdminAppeals,getAdminAppeal} from '../../api/appeal'
import {validAppealDetail,violationLabels} from '../../composables/appealForm.js'
import AppealRecord from '../AppealRecord.vue'
import SButton from '../ui/SButton.vue'
import SSelect from '../ui/SSelect.vue'
import SBanner from '../ui/SBanner.vue'
const items=ref([]),loaded=ref(false),loading=ref(false),error=ref(''),status=ref('submitted'),detail=ref(null),detailLoading=ref(false),detailError=ref(''),selectedId=ref(null);let alive=true,listSequence=0,detailSequence=0
async function loadList(){const ticket=++listSequence;loading.value=true;error.value='';try{const response=await listAdminAppeals(status.value?{status:status.value}:{});if(!alive||ticket!==listSequence)return;if(!Array.isArray(response.data))throw new Error('管理申诉列表返回不完整');items.value=response.data;loaded.value=true}catch(failure){if(alive&&ticket===listSequence)error.value=failure.message}finally{if(alive&&ticket===listSequence)loading.value=false}}
async function openDetail(id){const ticket=++detailSequence;selectedId.value=id;detail.value=null;detailLoading.value=true;detailError.value='';try{const response=await getAdminAppeal(id);if(!alive||ticket!==detailSequence)return;if(!validAppealDetail(response.data)||response.data.id!==id||!Number.isSafeInteger(response.data.subject?.id))throw new Error('管理申诉详情返回不完整');detail.value=response.data}catch(failure){if(alive&&ticket===detailSequence)detailError.value=failure.message}finally{if(alive&&ticket===detailSequence)detailLoading.value=false}}
onMounted(loadList);onBeforeUnmount(()=>{alive=false;listSequence++;detailSequence++});defineExpose({loadList})
</script>
<template><section class="appeal-management"><section class="card"><h3>申诉待办</h3><p>当前查看本人提交的申诉及原材料。待审核不等于已撤销违规或解除限制。</p><form class="filter" @submit.prevent="loadList"><label>状态<SSelect v-model="status" :options="[{value:'submitted',label:'待审核'},{value:null,label:'全部已登记申诉'}]" :disabled="loading" /></label><SButton type="submit" :loading="loading">应用并刷新</SButton></form><p v-if="loading" role="status">正在读取管理申诉列表…</p><SBanner v-else-if="error" type="error" :title="error"><SButton @click="loadList">重试查询</SButton></SBanner><p v-else-if="!loaded">尚未读取管理申诉。</p><template v-else><p v-if="!items.length">当前条件暂无申诉。</p><ul><li v-for="item in items" :key="item.id"><p>申诉#{{item.id}} · 违规#{{item.violation_id}} · {{item.status==='submitted'?'待审核':item.status}} · {{item.submitted_at}}</p><p v-if="item.subject">申诉人：#{{item.subject.id}} {{item.subject.real_name}} / {{item.subject.username}}</p><SButton size="sm" @click="openDetail(item.id)">查看原件和进度</SButton></li></ul></template></section><section v-if="selectedId" class="card"><h3>管理申诉详情#{{selectedId}}</h3><SButton :loading="detailLoading" @click="openDetail(selectedId)">刷新原件</SButton><p v-if="detailLoading" role="status">正在鉴权读取原申诉与材料…</p><SBanner v-else-if="detailError" type="error" :title="detailError" /><template v-if="detail&&!detailLoading&&!detailError"><p>申诉人：#{{detail.subject.id}} {{detail.subject.real_name}} / {{detail.subject.username}} · {{detail.subject.campus_id||'校园编号未登记'}} · {{detail.subject.role==='staff'?'教职工':detail.subject.role==='student'?'学生':'管理员'}} · {{detail.subject.status==='active'?'启用':'停用'}}</p><section class="management-context"><h4>管理核查来源（当前）</h4><template v-if="detail.management_context?.violation"><p>当前违规#{{detail.management_context.violation.id}} · 主体账号#{{detail.management_context.violation.user_id}} · {{violationLabels[detail.management_context.violation.type]||detail.management_context.violation.type}} · {{detail.management_context.violation.source==='manual'?'管理员核实后登记':detail.management_context.violation.source==='automatic'?'系统自动事件':detail.management_context.violation.source}} · 当前{{detail.management_context.violation.status==='active'?'有效':detail.management_context.violation.status==='revoked'?'已撤销':detail.management_context.violation.status}}</p><p>发生：{{detail.management_context.violation.occurred_at}}；登记：{{detail.management_context.violation.registered_at}}</p><p class="source-reason">当前公开事实依据：{{detail.management_context.violation.reason}}</p><p>原关联预约：<span v-if="detail.management_context.violation.reservation_id">#{{detail.management_context.violation.reservation_id}}</span><span v-else>未关联</span>；源核实事件：<span v-if="detail.management_context.violation.source_event_id">#{{detail.management_context.violation.source_event_id}}</span><span v-else>无已关联源核实事件</span>；登记人账号：<span v-if="detail.management_context.violation.registrant_id">#{{detail.management_context.violation.registrant_id}}</span><span v-else>无已关联登记人账号</span></p><p v-if="detail.management_context.source_complaint_id">来源投诉#{{detail.management_context.source_complaint_id}}；可切换投诉管理，按该投诉编号和源核实事件核查。</p><p v-else>无已关联来源投诉。</p><p>此区是管理当前事实，与下方提交时快照分开保留，不代表已完成审核。</p></template><p v-else>管理核查来源尚未返回，请刷新核对；不以本人安全快照代替管理来源。</p></section><AppealRecord :record="detail" /></template></section></section></template>
<style scoped>.appeal-management,.appeal-management>.card{display:grid;gap:16px;min-width:0;overflow-wrap:anywhere}.management-context{display:grid;gap:8px;padding:12px;background:var(--surface-2);border-radius:var(--r-md)}.source-reason{white-space:pre-wrap}.filter{display:flex;flex-wrap:wrap;gap:12px;align-items:end}.filter label{display:grid;gap:7px}.appeal-management ul{display:grid;gap:14px;padding-left:22px}</style>
